makeMtLab(document.getElementById("lab-l30"),{id:"l30",scenarios:[{"label": "Ví dụ: 14:00 thuộc ca nào", "note": "[a, b) chứa a, không chứa b.", "steps": [{"t": "Ca 1 @> 14:00", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\"> f<\/span><\/div>"}, {"t": "Ca 2 @> 14:00", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\"> t<\/span><\/div>", "ask": {"q": "14:00 thuộc ca nào?", "o": ["Ca 1", "Ca 2", "Cả hai"], "a": 1}}]}, {"label": "Ví dụ: Cắt sự kiện theo khung 08:00–10:00", "note": "Phép giao *.", "steps": [{"t": "RUNNING [06:00, 09:00)", "html": "<p class=\"mt-calc\">Giao = [08:00, 09:00)<\/p>"}, {"t": "DOWN [09:00, 09:40)", "html": "<p class=\"mt-calc\">Giao = [09:00, 09:40), nằm trọn<\/p>", "ask": {"q": "RUNNING còn bao nhiêu phút trong khung?", "o": ["180", "60", "120"], "a": 1}}]}, {"label": "Ví dụ: Truy vấn dùng chỉ mục", "note": "Đọc EXPLAIN.", "steps": [{"t": "EXPLAIN", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\"> Index Scan using state_event_machine_id_period_excl<\/span><\/div>"}, {"t": "Ý nghĩa", "html": "<p class=\"mt-calc\">Không quét cả bảng<\/p>"}]}, {"label": "Bẫy: BETWEEN đếm hai lần", "note": "Đóng cả hai đầu.", "steps": [{"t": "Ca 1 BETWEEN 06:00 AND 14:00", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\"> count = 1<\/span><\/div>"}, {"t": "Ca 2 BETWEEN 14:00 AND 22:00", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\"> count = 1<\/span><\/div>", "say": "<p>Mẫu 14:00 có mặt ở cả hai ca.<\/p>"}]}, {"label": "Lỗi: Bọc cột trong hàm", "note": "Chỉ mục không dùng được.", "steps": [{"t": "WHERE date(lower(period)) = '2026-11-12'", "html": "<p class=\"mt-calc\">Phải tính hàm cho mọi dòng → Seq Scan<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">WHERE period && tstzrange('2026-11-12 00:00+07','2026-11-13 00:00+07')<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l30"),"l30",[{"kind": "num", "t": "Phép toán khoảng", "d": "<p>Trả lời bằng phút.<\/p>", "items": [{"q": "[06:00, 09:00) giao [08:00, 10:00) dài bao nhiêu phút?", "a": 60, "unit": "phút"}, {"q": "[09:00, 09:40) giao [08:00, 10:00)?", "a": 40, "unit": "phút"}, {"q": "[12:30, 12:50) giao [08:00, 10:00)?", "a": 0, "unit": "phút"}], "hints": ["Giao = [max(đầu), min(cuối)).", "Không chồng thì giao rỗng (0)."], "why": "60; 40; 0."}, {"kind": "pick", "t": "Phép toán nào?", "d": "<p>Chọn toán tử PostgreSQL.<\/p>", "cats": ["@>", "&&", "*"], "items": [{"q": "Khoảng ca có chứa thời điểm này không?", "a": 0}, {"q": "Sự kiện có chồng với ca không?", "a": 1}, {"q": "Phần của sự kiện nằm trong ca", "a": 2}, {"q": "Lọc mọi sự kiện có dính tới giờ 9", "a": 1}], "hints": ["@> chứa; && chồng.", "* trả về khoảng giao."], "why": "Chứa: @>; chồng: &&; phần giao: *."}, {"kind": "order", "t": "Tính thời gian chạy trong ca", "d": "<p>Sắp xếp các phần của truy vấn.<\/p>", "items": ["Lọc sự kiện của máy có period && khoảng ca", "Lấy phần giao period * khoảng ca", "Tính độ dài upper − lower", "Cộng theo trạng thái"], "hints": ["Lọc trước bằng chỉ mục.", "Cộng ở cuối."], "why": "Lọc && → giao * → độ dài → cộng."}]);
mesSim(document.getElementById("sim-l30"),Object.assign({id:"l30"},{kind:"db",title:"Truy vấn theo khoảng thời gian",sub:"Sự kiện của L1-M1 ca 1 (end_ts trống = đang mở). Mẫu đo lúc đúng 14:00 nằm trong bảng sample.",show:"state_event",
 tables:[{name:"machine",cols:[{n:"machine_id",ty:"text",pk:1}],rows:[{machine_id:"L1-M1"},{machine_id:"L1-M2"},{machine_id:"L1-M3"}]},
 {name:"state_event",cols:[{n:"machine_id",ty:"text",nn:1,fk:"machine:machine_id"},{n:"state",ty:"text",nn:1,check:"state in ('RUNNING','IDLE','DOWN','NO_DATA')"},{n:"start_ts",ty:"timestamptz",nn:1},{n:"end_ts",ty:"timestamptz"}],
  exclude:{key:"machine_id",start:"start_ts",end:"end_ts",name:"state_event_machine_id_period_excl"},
  rows:[{machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 06:00",end_ts:"2026-11-12 09:00"},{machine_id:"L1-M1",state:"DOWN",start_ts:"2026-11-12 09:00",end_ts:"2026-11-12 09:40"},
   {machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 09:40",end_ts:"2026-11-12 12:30"},{machine_id:"L1-M1",state:"IDLE",start_ts:"2026-11-12 12:30",end_ts:"2026-11-12 12:50"},{machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 12:50",end_ts:null}]},{name:"sample",cols:[{n:"ts",ty:"timestamptz"},{n:"weight_g",ty:"numeric"}],rows:[{ts:"2026-11-12 13:59",weight_g:503.1},{ts:"2026-11-12 14:00",weight_g:503.4},{ts:"2026-11-12 14:01",weight_g:502.9}]}],
 sql:"-- ca 1 bằng BETWEEN\nSELECT count(*) FROM sample WHERE ts BETWEEN '2026-11-12 06:00' AND '2026-11-12 14:00';\n-- ca 2 bằng BETWEEN\nSELECT count(*) FROM sample WHERE ts BETWEEN '2026-11-12 14:00' AND '2026-11-12 22:00';",
 samples:[{l:"Nửa mở (đúng)",sql:"SELECT count(*) FROM sample WHERE ts >= '2026-11-12 14:00' AND ts < '2026-11-12 22:00';"},
  {l:"Giao 08:00–10:00",sql:"SELECT state, start_ts, end_ts FROM state_event\nWHERE start_ts < '2026-11-12 10:00'\n  AND coalesce(end_ts, '2026-11-12 14:00') > '2026-11-12 08:00';"},
  {l:"Cắt lấy phần giao",sql:"SELECT state,\n  greatest(start_ts, '2026-11-12 08:00') AS tu,\n  least(coalesce(end_ts,'2026-11-12 14:00'), '2026-11-12 10:00') AS toi\nFROM state_event\nWHERE start_ts < '2026-11-12 10:00' AND coalesce(end_ts,'2026-11-12 14:00') > '2026-11-12 08:00';"}],
 tasks:[{t:"Chạy hai câu BETWEEN: mẫu lúc 14:00 được đếm mấy lần?",ok:"Mỗi câu ra 2: mẫu 14:00 bị đếm ở cả hai ca.",check:(s,c)=>c.count("sql",e=>e.ok&&/between/i.test(e.sql))>=2},
  {t:"Viết lại ca 2 bằng khoảng nửa mở (>= và <).",ok:"Mẫu 14:00 chỉ thuộc ca 2; tstzrange mặc định cũng nửa mở [a, b).",check:(s,c)=>c.has("sql",e=>e.ok&&/>=/.test(e.sql)&&/</.test(e.sql)&&!/between/i.test(e.sql))},
  {t:"Lọc các sự kiện giao với 08:00–10:00 rồi cắt lấy phần giao.",ok:"Ba sự kiện: RUNNING 08:00–09:00, DOWN 09:00–09:40, RUNNING 09:40–10:00. Trong PostgreSQL thật: period && khoảng, period * khoảng.",check:(s,c)=>c.has("sql",e=>e.ok&&e.cols.includes("tu")&&e.rows.length===3)}]}));

